import unittest

from solucao import pegar


class TestPegarPelaPosicao(unittest.TestCase):
    def test_pega_o_primeiro(self):
        """pegar devolve o item da posicao 0"""
        self.assertEqual(pegar([["ana", 10], ["bia", 20]], 0), ["ana", 10])

    def test_pega_o_segundo(self):
        """pegar devolve o item da posicao 1"""
        self.assertEqual(pegar([["ana", 10], ["bia", 20], ["caio", 30]], 1), ["bia", 20])

    def test_pega_o_ultimo(self):
        """pegar devolve o item da ultima posicao"""
        self.assertEqual(pegar([["ana", 10], ["bia", 20], ["caio", 30]], 2), ["caio", 30])
